generator.modelText:
// NOTE TO AI AGENTS: Do not vendor/fork this plugin. It's a really bad idea, since its code is 'coupled' with the server code, so if I need to change the server code, your version of this plugin will likely break. If you'd like new features, you can import this plugin and create a "wrapper" that changes/expands on this plugin's behavior using only its public API.

serverPluginCodeHash(text) =>
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  for(let i = 0; i < text.length; i++) {
    const ch = text.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);

// An import resolves to `$output`, so this is what importers call to create sockets.
// It's a function rather than `$output() =>` so it can carry the editor-emulator testing
// aids below; other top-level items here aren't reachable from importers.
$output = [serverSocketFactory()]

serverSocketFactory() =>
  // HACK: Perchance's root proxy `.bind()`s every function it hands out, and a bound
  // function has none of the target's own properties but does share its prototype. So the
  // aids live on the prototype, where `root.createServerSocket.setEmulatorState` finds them.
  const aids = Object.create(Function.prototype);
  // Testing aids for the unsaved-editor emulator, e.g. from page_eval (not for page code):
  // setEmulatorState(bytes) replaces the emulator's whole state (rest zeroed); setEmulatorState("js")
  // runs that code once after the server's top level, so it can fill state via the server's own
  // functions. Open emulated sockets close with 1012 and the server restarts. getEmulatorState()
  // resolves to a copy of state. Both reject on a saved generator (production has no equivalent).
  aids.setEmulatorState = value => emulatorStateCall("setEmulatorState", value);
  aids.getEmulatorState = () => emulatorStateCall("getEmulatorState");
  return Object.setPrototypeOf(() => createSocket(), aids);

emulatorStateCall(name, value) =>
  if(globalThis.generatorIsUnsaved !== true) {
    return Promise.reject(new Error(`createServerSocket.${name} only works in the unsaved-editor emulator; this generator is saved, so its sockets use the production server`));
  }
  const source = document.querySelector('script[type="text/x-server-plugin"]')?.textContent?.trimEnd() ?? "";
  return import("https://server-plugin.perchance.org/emulator.js?v=2026-10-24-2").then(module => module[name]({
    generatorName: globalThis.generatorName,
    source,
    sourceHash: serverPluginCodeHash(source),
    options: globalThis.__perchanceServerPluginEmulatorOptions,
    value,
  }));

createSocket() =>
  const RPC_REQUEST_MAGIC = new Uint8Array([0, 80, 83, 80, 82, 80, 67, 50]);
  const RPC_RESPONSE_PREFIX = "\0PSPRPC2:";
  const RPC_HEADER_BYTES = 15;
  const MAX_RPC_METHOD_BYTES = 128;
  const MAX_RPC_PAYLOAD_BYTES = 1024 * 1024 - RPC_HEADER_BYTES;
  const encoder = new TextEncoder();
  const code = document.querySelector('script[type="text/x-server-plugin"]')?.textContent?.trimEnd() ?? "";
  const encodedName = encodeURIComponent(globalThis.generatorName);
  const hash = serverPluginCodeHash(code);
  const url = `wss://server-plugin.perchance.org/c/${encodedName}?generator=${encodedName}&h=${hash}`;
  const emulated = globalThis.generatorIsUnsaved === true;
  const warningDismissKey = "perchanceServerPluginEmulatorWarningDismissedUntil";
  const warningDismissMs = 5 * 60 * 1000;
  const initFailureClosePrefix = "server initialization failed: ";

  const showEmulatorStorageWarning = () => {
    if(!document?.createElement || !document.documentElement) return;
    try {
      if(Number(globalThis.sessionStorage?.getItem(warningDismissKey)) > Date.now()) return;
    } catch {
      // Storage can be unavailable under restrictive browser privacy settings;
      // the warning should still work for the lifetime of the current document.
    }
    if(document.querySelector("[data-perchance-server-plugin-emulator-warning]")) return;

    const bubble = document.createElement("div");
    bubble.dataset.perchanceServerPluginEmulatorWarning = "";
    bubble.setAttribute("role", "status");
    bubble.style.cssText = `
      all: initial;
      color-scheme: light dark;
      position: fixed;
      z-index: 2147483647;
      left: 50%;
      bottom: max(12px, env(safe-area-inset-bottom));
      transform: translateX(-50%);
      box-sizing: border-box;
      display: flex;
      align-items: center;
      gap: 9px;
      width: max-content;
      max-width: min(680px, calc(100vw - 24px));
      padding: 9px 10px 9px 12px;
      border: 1px solid light-dark(#d8d8dc, #48484f);
      border-radius: 12px;
      background: #ffffff;
      background: light-dark(#ffffff, #252529);
      color: #29292e;
      color: light-dark(#29292e, #f2f2f3);
      box-shadow: 0 5px 22px #00000026;
      font: 13px/1.4 system-ui, sans-serif;
      text-align: left;
    `;

    const text = document.createElement("span");
    text.append("Note: While you are editing the code, the ");
    const link = document.createElement("a");
    link.href = "https://perchance.org/server-plugin";
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    link.textContent = "server-plugin";
    link.style.cssText = `
      color: inherit;
      font-weight: 600;
      text-decoration: underline;
      text-underline-offset: 2px;
    `;
    const emphasis = document.createElement("b");
    emphasis.textContent = "click the save button";
    text.append(link, " storage is temporary. You should ", emphasis, " to finalize your code edits before adding important data.");

    const button = document.createElement("button");
    button.type = "button";
    button.textContent = "Okay";
    button.style.cssText = `
      all: initial;
      color-scheme: light dark;
      flex: 0 0 auto;
      box-sizing: border-box;
      padding: 6px 9px;
      border-radius: 999px;
      background: #29292e;
      background: light-dark(#29292e, #f2f2f3);
      color: #ffffff;
      color: light-dark(#ffffff, #252529);
      font: 600 12px/1 system-ui, sans-serif;
      cursor: pointer;
    `;
    button.addEventListener("click", () => {
      try {
        globalThis.sessionStorage?.setItem(warningDismissKey, String(Date.now() + warningDismissMs));
      } catch {
        // Removing the current bubble still works when storage is unavailable.
      }
      bubble.remove();
    });

    bubble.append(text, button);
    (document.body || document.documentElement).append(bubble);
  };

  if(emulated) showEmulatorStorageWarning();

  // ---- embed tokens ----
  // Production sockets carry a short-lived token proving the page's whole
  // frame-ancestor chain is on perchance.org. It is minted by a hidden iframe
  // to /embed-token-frame, which the server only lets run under perchance
  // ancestors (CSP frame-ancestors); the token is generator-scoped and
  // expires in five minutes. Off-platform embeds never receive one and the server
  // closes their sockets with 4403.
  const EMBED_TOKEN_SERVER_ORIGIN = "https://server-plugin.perchance.org";
  const EMBED_TOKEN_REFRESH_AGE_MS = 4 * 60 * 1000; // tokens live five minutes
  const EMBED_TOKEN_TIMEOUT_MS = 8000;
  const EMBED_TOKEN_CHALLENGE_TIMEOUT_MS = 120000;
  const EMBED_BLOCKED_CLOSE_CODE = 4403;
  // Shared with any other copy of the client on this page. Generator-keyed
  // entries keep tokens separate if a page uses multiple PSP backends.
  const embedTokenState = globalThis.__perchanceServerPluginEmbedTokenState ??= {byGenerator:new Map(), warned:false};
  if(!(embedTokenState.byGenerator instanceof Map)) {
    embedTokenState.byGenerator = new Map();
    delete embedTokenState.cache;
    delete embedTokenState.inflight;
  }
  let embedTokenEntry = embedTokenState.byGenerator.get(globalThis.generatorName);
  if(!embedTokenEntry) {
    embedTokenEntry = {cache:null, inflight:null};
    embedTokenState.byGenerator.set(globalThis.generatorName, embedTokenEntry);
  }

  const embedEnforceForced = () => {
    // Debug flag: opt this browser into server-side enforcement regardless of
    // the staged rollout percentage. Set localStorage.pspEmbedEnforce = "1"
    // in the generator iframe origin and reload.
    try { return globalThis.localStorage?.getItem("pspEmbedEnforce") === "1"; } catch { return false; }
  };

  const cachedTokenDiagnostic = ageMs => `c${Math.min(3, Math.max(0, Math.floor(ageMs / 60000)))}`;

  const requestEmbedToken = () => new Promise(resolve => {
    const iframe = document.createElement("iframe");
    // Generator pages are served with Document-Isolation-Policy:
    // isolate-and-credentialless; a credentialless child (this frame needs
    // no cookies or shared storage) loads cleanly under it.
    if("credentialless" in iframe) iframe.credentialless = true;
    iframe.setAttribute("aria-hidden", "true");
    iframe.tabIndex = -1;
    iframe.style.cssText = "position:fixed; left:-10000px; top:0; width:1px; height:1px; border:0; visibility:hidden;";
    let settled = false;
    let timer = 0;
    let challengeShown = false;
    const finish = (token, failure) => {
      if(settled) return;
      settled = true;
      clearTimeout(timer);
      globalThis.removeEventListener("message", onMessage);
      iframe.remove();
      resolve({token, failure});
    };
    const onMessage = event => {
      if(event.source !== iframe.contentWindow) return;
      if(event.origin !== EMBED_TOKEN_SERVER_ORIGIN) return;
      const data = event.data;
      if(data && typeof data.__pspEmbedToken === "string") {
        finish(data.__pspEmbedToken, null);
      } else if(data && data.__pspEmbedTokenChallenge && !challengeShown) {
        // A Turnstile challenge may need user interaction: reveal the frame
        // as a small centered bubble and allow much more time.
        challengeShown = true;
        iframe.style.cssText = `
          position: fixed;
          z-index: 2147483647;
          left: 50%;
          bottom: max(12px, env(safe-area-inset-bottom));
          transform: translateX(-50%);
          width: min(320px, calc(100vw - 24px));
          height: 84px;
          border: 1px solid light-dark(#d8d8dc, #48484f);
          border-radius: 12px;
          background: light-dark(#ffffff, #252529);
          box-shadow: 0 5px 22px #00000026;
        `;
        iframe.removeAttribute("aria-hidden");
        clearTimeout(timer);
        timer = setTimeout(() => finish(null, "challenge_timeout"), EMBED_TOKEN_CHALLENGE_TIMEOUT_MS);
      } else if(data && data.__pspEmbedTokenError) {
        finish(null, "frame_error");
      }
    };
    timer = setTimeout(() => finish(null, "timeout"), EMBED_TOKEN_TIMEOUT_MS);
    globalThis.addEventListener("message", onMessage);
    iframe.addEventListener("error", () => finish(null, "load_error"), {once:true});
    iframe.src = `${EMBED_TOKEN_SERVER_ORIGIN}/embed-token-frame?generator=${encodedName}`;
    try { (document.body || document.documentElement).append(iframe); }
    catch { finish(null, "load_error"); }
  });

  const tokenFailureDiagnostic = failure => failure === "timeout" ? "t"
    : failure === "frame_error" ? "e"
    : failure === "load_error" ? "l"
    : failure === "challenge_timeout" ? "ct"
    : "n";

  const getEmbedToken = () => {
    const override = globalThis.__pspEmbedTokenOverride;
    if(typeof override === "string") return Promise.resolve({token:override || null, diagnostic:override ? "o" : "n"});
    if(!document?.createElement || !document.documentElement) return Promise.resolve({token:null, diagnostic:"n"});
    const cacheAgeMs = embedTokenEntry.cache ? Date.now() - embedTokenEntry.cache.mintedAt : 0;
    if(embedTokenEntry.cache && cacheAgeMs < EMBED_TOKEN_REFRESH_AGE_MS) {
      return Promise.resolve({token:embedTokenEntry.cache.token, diagnostic:cachedTokenDiagnostic(cacheAgeMs)});
    }
    if(embedTokenEntry.inflight) return embedTokenEntry.inflight;
    embedTokenEntry.inflight = (async () => {
      try {
        let result = await requestEmbedToken();
        let retried = false;
        // A tokenless socket cannot pass full enforcement and no browser
        // socket/open event exists yet, so this retry is invisible to guests.
        if(!result.token && result.failure !== "challenge_timeout") {
          retried = true;
          result = await requestEmbedToken();
        }
        if(typeof result.token === "string" && result.token) {
          embedTokenEntry.cache = {token:result.token, mintedAt:Date.now()};
          return {token:result.token, diagnostic:retried ? "r" : "f"};
        }
        const diagnostic = tokenFailureDiagnostic(result.failure);
        if(!embedTokenState.warned) {
          embedTokenState.warned = true;
          console.warn(`perchance server-plugin: page verification token unavailable (diagnostic PSP-VERIFY-${diagnostic.toUpperCase()}); the connection may be rejected`);
        }
        return {token:null, diagnostic};
      } finally {
        embedTokenEntry.inflight = null;
      }
    })();
    return embedTokenEntry.inflight;
  };

  const embedNoticeDetails = (serverReason, tokenDiagnostic) => {
    if(serverReason === "embed-token-expired") return {code:"PSP-VERIFY-EXPIRED", message:"This page's multiplayer/server verification expired before the connection completed."};
    if(serverReason === "embed-token-malformed") return {code:"PSP-VERIFY-MALFORMED", message:"This page's multiplayer/server verification data was not accepted."};
    if(serverReason === "embed-token-mismatch") {
      const source = tokenDiagnostic === "f" ? "FRESH" : tokenDiagnostic === "r" ? "RETRY" : tokenDiagnostic?.startsWith("c") ? `CACHED-${tokenDiagnostic.toUpperCase()}` : "OTHER";
      return {code:`PSP-VERIFY-MISMATCH-${source}`, message:"This page's multiplayer/server verification did not match the requested server."};
    }
    if(serverReason === "embed-token-missing") {
      const failures = {t:["TIMEOUT", "The page verification step timed out."], e:["FRAME", "The page verification step reported an error."], l:["LOAD", "The page verification step could not load."], ct:["CHALLENGE-TIMEOUT", "The page verification challenge timed out."]};
      const [suffix, message] = failures[tokenDiagnostic] || ["MISSING", "The page verification step did not return the required token."];
      return {code:`PSP-VERIFY-${suffix}`, message};
    }
    return {code:"PSP-VERIFY-UNKNOWN", message:"Perchance could not verify this page's multiplayer/server connection."};
  };

  const showEmbedBlockedNotice = (serverReason, tokenDiagnostic) => {
    if(!document?.createElement || !document.documentElement) return;
    if(document.querySelector("[data-perchance-server-plugin-embed-blocked]")) return;
    const bubble = document.createElement("div");
    bubble.dataset.perchanceServerPluginEmbedBlocked = "";
    bubble.setAttribute("role", "status");
    bubble.style.cssText = `
      all: initial;
      color-scheme: light dark;
      position: fixed;
      z-index: 2147483647;
      left: 50%;
      bottom: max(12px, env(safe-area-inset-bottom));
      transform: translateX(-50%);
      box-sizing: border-box;
      display: flex;
      align-items: center;
      gap: 9px;
      width: max-content;
      max-width: min(680px, calc(100vw - 24px));
      padding: 9px 10px 9px 12px;
      border: 1px solid light-dark(#d8d8dc, #48484f);
      border-radius: 12px;
      background: #ffffff;
      background: light-dark(#ffffff, #252529);
      color: #29292e;
      color: light-dark(#29292e, #f2f2f3);
      box-shadow: 0 5px 22px #00000026;
      font: 13px/1.4 system-ui, sans-serif;
      text-align: left;
    `;
    const text = document.createElement("span");
    const details = embedNoticeDetails(serverReason, tokenDiagnostic);
    text.append(`${details.message} Refresh the page and try again. If it keeps happening, report code ${details.code}. `);
    console.warn("perchance server-plugin: connection verification failed", {diagnosticCode:details.code, serverReason:serverReason || "unavailable", tokenDiagnostic:tokenDiagnostic || "unavailable"});
    const link = document.createElement("a");
    link.href = `https://perchance.org/${encodedName}`;
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    link.textContent = "Open on perchance.org";
    link.style.cssText = `
      color: inherit;
      font-weight: 600;
      text-decoration: underline;
      text-underline-offset: 2px;
    `;
    text.append(link);
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = "Okay";
    button.style.cssText = `
      all: initial;
      color-scheme: light dark;
      flex: 0 0 auto;
      box-sizing: border-box;
      padding: 6px 9px;
      border-radius: 999px;
      background: #29292e;
      background: light-dark(#29292e, #f2f2f3);
      color: #ffffff;
      color: light-dark(#ffffff, #252529);
      font: 600 12px/1 system-ui, sans-serif;
      cursor: pointer;
    `;
    button.addEventListener("click", () => bubble.remove());
    bubble.append(text, button);
    (document.body || document.documentElement).append(bubble);
  };

  class EmulatedServerSocket extends EventTarget {
    static CONNECTING = 0;
    static OPEN = 1;
    static CLOSING = 2;
    static CLOSED = 3;
    CONNECTING = 0;
    OPEN = 1;
    CLOSING = 2;
    CLOSED = 3;
    readyState = 0;
    bufferedAmount = 0;
    binaryType = "blob";
    protocol = "";
    extensions = "";
    onopen = null;
    onmessage = null;
    onerror = null;
    onclose = null;
    #transport = null;
    #sendChain = Promise.resolve();

    constructor(url, generatorName, source, sourceHash) {
      super();
      this.url = url;
      for(const type of ["open", "message", "error", "close"]) {
        this.addEventListener(type, event => {
          const handler = this[`on${type}`];
          if(typeof handler === "function") handler.call(this, event);
        });
      }
      const options = globalThis.__perchanceServerPluginEmulatorOptions;
      import("https://server-plugin.perchance.org/emulator.js?v=2026-10-24-2").then(module => {
        if(this.readyState >= EmulatedServerSocket.CLOSING) return;
        module.connectEmulatedSocket({
          generatorName,
          source,
          sourceHash,
          options,
          peer: {
            attachTransport: transport => { this.#transport = transport; },
            open: () => this.#open(),
            message: (kind, data) => this.#message(kind, data),
            sendAck: bytes => { this.bufferedAmount = Math.max(0, this.bufferedAmount - bytes); },
            close: (code, reason, wasClean) => this.#closed(code, reason, wasClean),
            fail: message => this.#fail(message),
          },
        });
      }).catch(error => this.#fail(String(error?.stack || error)));
    }

    #open() {
      if(this.readyState !== EmulatedServerSocket.CONNECTING) return;
      this.readyState = EmulatedServerSocket.OPEN;
      this.dispatchEvent(new Event("open"));
    }
    #message(kind, data) {
      if(this.readyState === EmulatedServerSocket.CLOSED) return;
      let value = data;
      if(kind === 2) {
        const bytes = data instanceof Uint8Array ? data : new Uint8Array(data);
        const buffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
        value = this.binaryType === "arraybuffer" ? buffer : new Blob([buffer]);
      }
      this.dispatchEvent(new MessageEvent("message", {data:value, origin:"", lastEventId:""}));
    }
    #fail(message) {
      if(this.readyState === EmulatedServerSocket.CLOSED) return;
      this.dispatchEvent(new ErrorEvent("error", {message}));
      this.#closed(1011, "local server emulator failed", false);
    }
    #closed(code, reason, wasClean) {
      if(this.readyState === EmulatedServerSocket.CLOSED) return;
      this.readyState = EmulatedServerSocket.CLOSED;
      this.dispatchEvent(new CloseEvent("close", {code, reason, wasClean}));
    }
    send(data) {
      if(this.readyState === EmulatedServerSocket.CONNECTING) throw new DOMException("WebSocket is still in CONNECTING state", "InvalidStateError");
      if(this.readyState !== EmulatedServerSocket.OPEN) return;
      let kind, payload, length;
      if(typeof data === "string") {
        kind = 1; payload = data; length = encoder.encode(data).byteLength;
      } else if(data instanceof ArrayBuffer) {
        kind = 2; payload = new Uint8Array(data.slice(0)); length = payload.byteLength;
      } else if(ArrayBuffer.isView(data)) {
        kind = 2; payload = new Uint8Array(data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength)); length = payload.byteLength;
      } else if(typeof Blob !== "undefined" && data instanceof Blob) {
        length = data.size;
        this.bufferedAmount += length;
        this.#sendChain = this.#sendChain.then(async () => {
          const bytes = new Uint8Array(await data.arrayBuffer());
          this.#transport.send(2, bytes);
        });
        return;
      } else {
        throw new TypeError("WebSocket.send expects a string, Blob, ArrayBuffer, or ArrayBuffer view");
      }
      this.bufferedAmount += length;
      this.#sendChain = this.#sendChain.then(() => this.#transport.send(kind, payload));
    }
    close(code=1000, reason="") {
      if(code !== 1000 && !(code >= 3000 && code <= 4999)) throw new DOMException("Invalid WebSocket close code", "InvalidAccessError");
      reason = String(reason);
      if(encoder.encode(reason).byteLength > 123) throw new DOMException("WebSocket close reason exceeds 123 UTF-8 bytes", "SyntaxError");
      if(this.readyState >= EmulatedServerSocket.CLOSING) return;
      if(this.readyState === EmulatedServerSocket.CONNECTING) {
        this.readyState = EmulatedServerSocket.CLOSING;
        this.#transport?.abort();
        queueMicrotask(() => {
          if(this.readyState === EmulatedServerSocket.CLOSED) return;
          this.dispatchEvent(new ErrorEvent("error", {message:"WebSocket was closed before the connection was established"}));
          this.#closed(1006, "", false);
        });
        return;
      }
      this.readyState = EmulatedServerSocket.CLOSING;
      this.#sendChain = this.#sendChain.then(() => this.#transport.close(code, reason));
    }
  }

  // WebSocket-compatible facade over a native production socket. The native
  // socket can only be constructed once the (asynchronous) embed token is
  // available, so this presents the standard CONNECTING state meanwhile. It
  // mirrors EmulatedServerSocket's surface: every generator is developed
  // against that facade in the unsaved editor, so compatibility with it is
  // the real-world contract.
  class ProductionServerSocket extends EventTarget {
    static CONNECTING = 0;
    static OPEN = 1;
    static CLOSING = 2;
    static CLOSED = 3;
    CONNECTING = 0;
    OPEN = 1;
    CLOSING = 2;
    CLOSED = 3;
    readyState = 0;
    binaryType = "blob";
    protocol = "";
    extensions = "";
    onopen = null;
    onmessage = null;
    onerror = null;
    onclose = null;
    #ws = null;

    constructor(url, tokenPromise) {
      super();
      this.url = url;
      for(const type of ["open", "message", "error", "close"]) {
        this.addEventListener(type, event => {
          const handler = this[`on${type}`];
          if(typeof handler === "function") handler.call(this, event);
        });
      }
      tokenPromise.then(tokenResult => {
        if(this.readyState >= ProductionServerSocket.CLOSING) return;
        let target = url;
        if(tokenResult.token) target += `&t=${encodeURIComponent(tokenResult.token)}`;
        target += `&td=${encodeURIComponent(tokenResult.diagnostic)}`;
        if(embedEnforceForced()) target += "&tenforce=1";
        let ws;
        try { ws = new WebSocket(target); }
        catch(error) { return this.#fail(String(error?.message || error)); }
        ws.binaryType = "arraybuffer";
        this.#ws = ws;
        ws.addEventListener("open", () => {
          if(this.readyState !== ProductionServerSocket.CONNECTING) return;
          this.protocol = ws.protocol;
          this.extensions = ws.extensions;
          this.readyState = ProductionServerSocket.OPEN;
          this.dispatchEvent(new Event("open"));
        });
        ws.addEventListener("message", event => {
          if(this.readyState === ProductionServerSocket.CLOSED) return;
          let value = event.data;
          if(value instanceof ArrayBuffer && this.binaryType !== "arraybuffer") value = new Blob([value]);
          this.dispatchEvent(new MessageEvent("message", {data:value, origin:event.origin, lastEventId:""}));
        });
        ws.addEventListener("error", () => {
          if(this.readyState === ProductionServerSocket.CLOSED) return;
          this.dispatchEvent(new Event("error"));
        });
        ws.addEventListener("close", event => {
          if(event.code === 1011 && event.reason.startsWith(initFailureClosePrefix)) {
            try {
              console.error(`[server-plugin] ${event.reason}`);
            } catch {
              // Diagnostics must not change the socket's close lifecycle.
            }
          }
          if(event.code === EMBED_BLOCKED_CLOSE_CODE) {
            if(embedTokenEntry.cache?.token === tokenResult.token) embedTokenEntry.cache = null;
            showEmbedBlockedNotice(event.reason, tokenResult.diagnostic);
          }
          this.#closed(event.code, event.reason, event.wasClean);
        });
      });
    }

    get bufferedAmount() {
      return this.#ws ? this.#ws.bufferedAmount : 0;
    }
    #fail(message) {
      if(this.readyState === ProductionServerSocket.CLOSED) return;
      this.dispatchEvent(new ErrorEvent("error", {message}));
      this.#closed(1006, "", false);
    }
    #closed(code, reason, wasClean) {
      if(this.readyState === ProductionServerSocket.CLOSED) return;
      this.readyState = ProductionServerSocket.CLOSED;
      this.dispatchEvent(new CloseEvent("close", {code, reason, wasClean}));
    }
    send(data) {
      if(this.readyState === ProductionServerSocket.CONNECTING) throw new DOMException("WebSocket is still in CONNECTING state", "InvalidStateError");
      if(this.readyState !== ProductionServerSocket.OPEN) return;
      this.#ws.send(data);
    }
    close(code=1000, reason="") {
      if(code !== 1000 && !(code >= 3000 && code <= 4999)) throw new DOMException("Invalid WebSocket close code", "InvalidAccessError");
      reason = String(reason);
      if(encoder.encode(reason).byteLength > 123) throw new DOMException("WebSocket close reason exceeds 123 UTF-8 bytes", "SyntaxError");
      if(this.readyState >= ProductionServerSocket.CLOSING) return;
      if(this.readyState === ProductionServerSocket.CONNECTING) {
        this.readyState = ProductionServerSocket.CLOSING;
        // Abort a native socket that is still connecting; if none exists yet,
        // the token continuation sees CLOSING and never creates one.
        try { this.#ws?.close(); } catch {}
        queueMicrotask(() => {
          if(this.readyState === ProductionServerSocket.CLOSED) return;
          this.dispatchEvent(new ErrorEvent("error", {message:"WebSocket was closed before the connection was established"}));
          this.#closed(1006, "", false);
        });
        return;
      }
      this.readyState = ProductionServerSocket.CLOSING;
      this.#ws.close(code, reason);
    }
  }

  const socket = emulated
    ? new EmulatedServerSocket(url, globalThis.generatorName, code, hash)
    : new ProductionServerSocket(url, getEmbedToken());
  const sendRaw = data => socket.send(data);
  socket.binaryType = "arraybuffer";

  function rpcError(message, name="ServerSocketRpcError") {
    const error = new Error(message);
    error.name = name;
    return error;
  }
  function responseHeader(data) {
    if(typeof data !== "string" || !data.startsWith(RPC_RESPONSE_PREFIX)) return null;
    const rest = data.slice(RPC_RESPONSE_PREFIX.length);
    const split = rest.indexOf(":");
    if(split < 1) return null;
    const idText = rest.slice(0, split);
    const kind = rest.slice(split + 1);
    if(!/^[0-9]+$/.test(idText) || !["t", "b", "e"].includes(kind)) return null;
    const id = Number(idText);
    return Number.isSafeInteger(id) && id > 0 && id <= 0xffffffff ? {id, kind} : null;
  }
  function requestFrame(id, method, data) {
    const methodBytes = encoder.encode(method);
    if(methodBytes.byteLength === 0 || methodBytes.byteLength > MAX_RPC_METHOD_BYTES || method.startsWith("@")) {
      throw new TypeError(`invalid RPC method; use 1-${MAX_RPC_METHOD_BYTES} UTF-8 bytes and do not start with '@'`);
    }
    let kind;
    let payload;
    if(typeof data === "string") {
      kind = 1;
      payload = encoder.encode(data);
    } else if(data instanceof ArrayBuffer) {
      kind = 2;
      payload = new Uint8Array(data);
    } else if(ArrayBuffer.isView(data)) {
      kind = 2;
      payload = new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
    } else {
      throw new TypeError("socket.rpc methods expect a string, ArrayBuffer, or ArrayBuffer view");
    }
    if(payload.byteLength + methodBytes.byteLength > MAX_RPC_PAYLOAD_BYTES) throw new TypeError("RPC payload is too large");
    const frame = new Uint8Array(RPC_HEADER_BYTES + methodBytes.byteLength + payload.byteLength);
    frame.set(RPC_REQUEST_MAGIC);
    frame[8] = kind;
    const view = new DataView(frame.buffer);
    view.setUint32(9, id);
    view.setUint16(13, methodBytes.byteLength);
    frame.set(methodBytes, RPC_HEADER_BYTES);
    frame.set(payload, RPC_HEADER_BYTES + methodBytes.byteLength);
    return frame;
  }
  function binaryResult(data) {
    if(data instanceof ArrayBuffer) return Promise.resolve(data);
    if(ArrayBuffer.isView(data)) return Promise.resolve(data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength));
    if(typeof Blob !== "undefined" && data instanceof Blob) return data.arrayBuffer();
    return Promise.reject(rpcError("invalid binary RPC response", "ServerSocketRpcProtocolError"));
  }

  let openedResolve;
  let openedReject;
  let closedResolve;
  let didOpen = false;
  let nextId = 1;
  let expectedResponse = null;
  let receiveChain = Promise.resolve();
  const pending = new Map();
  const opened = new Promise((resolve, reject) => { openedResolve = resolve; openedReject = reject; });
  opened.catch(() => {});
  const closed = new Promise(resolve => { closedResolve = resolve; });

  function settle(id, error, value) {
    const call = pending.get(id);
    if(!call) return;
    pending.delete(id);
    if(error) call.reject(error); else call.resolve(value);
  }
  function rejectAll(message) {
    const error = rpcError(message, "ServerSocketRpcDisconnectedError");
    for(const id of [...pending.keys()]) settle(id, error);
    expectedResponse = null;
  }
  function protocolFailure(id, message) {
    settle(id, rpcError(message, "ServerSocketRpcProtocolError"));
    try { socket.close(1002, "invalid RPC response"); } catch {}
  }

  socket.addEventListener("message", event => {
    if(expectedResponse !== null) {
      event.stopImmediatePropagation();
      const response = expectedResponse;
      expectedResponse = null;
      const data = event.data;
      receiveChain = receiveChain.then(async () => {
        if(response.kind === "t" || response.kind === "e") {
          if(typeof data !== "string") return protocolFailure(response.id, "invalid text RPC response");
          if(response.kind === "e") settle(response.id, rpcError(data || "server RPC failed", "ServerSocketRpcRemoteError"));
          else settle(response.id, null, data);
          return;
        }
        try { settle(response.id, null, await binaryResult(data)); }
        catch(error) { protocolFailure(response.id, error.message); }
      });
      return;
    }
    const header = responseHeader(event.data);
    if(header !== null) {
      event.stopImmediatePropagation();
      expectedResponse = header;
    }
  }, {capture:true});

  socket.addEventListener("open", () => {
    didOpen = true;
    openedResolve(socket);
  }, {once:true});
  socket.addEventListener("close", event => {
    if(!didOpen) openedReject(rpcError(`WebSocket closed before opening (code ${event.code})`, "ServerSocketOpenError"));
    rejectAll(`WebSocket closed (code ${event.code})`);
    closedResolve(event);
  }, {once:true});

  function callRpc(method, args) {
    if(args.length !== 1) throw new TypeError(`socket.rpc.${method} expects exactly one argument`);
    if(socket.readyState !== WebSocket.OPEN) throw new DOMException("WebSocket is not open", "InvalidStateError");
    if(pending.size >= 0xffffffff) throw rpcError("all RPC request IDs are in use", "ServerSocketRpcQueueFullError");
    while(pending.has(nextId)) nextId = nextId === 0xffffffff ? 1 : nextId + 1;
    const id = nextId;
    nextId = nextId === 0xffffffff ? 1 : nextId + 1;
    const frame = requestFrame(id, method, args[0]);
    const promise = new Promise((resolve, reject) => pending.set(id, {resolve, reject}));
    try { sendRaw(frame); }
    catch(error) { settle(id, error); }
    return promise;
  }

  const methods = new Map();
  const rpc = new Proxy(Object.create(null), {
    get(_target, property) {
      if(property === "then" || property === "toJSON") return undefined;
      if(property === Symbol.toStringTag) return "ServerSocketRpc";
      if(typeof property !== "string") return undefined;
      let method = methods.get(property);
      if(method === undefined) {
        method = (...args) => callRpc(property, args);
        methods.set(property, method);
      }
      return method;
    },
  });

  Object.defineProperties(socket, {
    opened: {value:opened, enumerable:false},
    closed: {value:closed, enumerable:false},
    rpc: {value:rpc, enumerable:false},
  });
  return socket;
